(()=>{'use strict';
const D=window.ATELIER_DATA;
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const img=n=>`./assets/${encodeURIComponent(n||'tag')}.svg`;
const safePhoto=src=>typeof src==='string'&&/^data:image\/(?:jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(src)?src:null;
const time=()=>new Date().toISOString().slice(0,10);
const guid=()=>globalThis.crypto?.randomUUID?.()||('x'+Date.now().toString(36)+Math.random().toString(36).slice(2));
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',projects:'<path d="M4 8V3h16v5M3 11h18v10H3zM7 11v10M17 11v10M9 3v5M15 3v5"/>',course:'<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/>',journal:'<path d="M5 3h14v18H5zM9 7h6M9 11h6M9 15h4"/>',atelier:'<path d="M12 22a10 10 0 1 1 10-10c0 3-2 4-4 4h-2a2 2 0 0 0-2 2v2a2 2 0 0 1-2 2Z"/><circle cx="7" cy="12" r="1"/><circle cx="12" cy="7" r="1"/><circle cx="17" cy="11" r="1"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 1 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8z"/>',search:'<circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',back:'<path d="m14 18-6-6 6-6"/>',next:'<path d="m10 18 6-6-6-6"/>',check:'<path d="m4 12 5 5L20 6"/>',tag:'<path d="M3 3h11l7 7-11 11L3 14z"/><circle cx="9" cy="9" r="1"/>',book:'<path d="M3 4h8a3 3 0 0 1 3 3v14a3 3 0 0 0-3-3H3zM21 4h-5a3 3 0 0 0-3 3"/>',layers:'<path d="m12 3 9 5-9 5-9-5zM3 12l9 5 9-5M3 16l9 5 9-5"/>',stamp:'<path d="M7 12h10l2 5H5l2-5zM9 12V8a3 3 0 0 1 6 0v4M4 21h16"/>',droplets:'<path d="M12 3c-2 5-6 8-6 12a6 6 0 0 0 12 0c0-4-4-7-6-12z"/>',sparkles:'<path d="m12 2 2.4 7.6L22 12l-7.6 2.4L12 22l-2.4-7.6L2 12l7.6-2.4z"/>',camera:'<path d="M3 7h4l2-3h6l2 3h4v13H3z"/><circle cx="12" cy="13" r="4"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',upload:'<path d="M12 20V8m-4 4 4-4 4 4M4 7V3h16v4"/>',trash:'<path d="M4 7h16M10 7V4h4v3M7 7l1 14h8l1-14"/>',edit:'<path d="M4 20h5l11-11-5-5L4 15zM13 6l5 5"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6M12 7h.01"/>',leaf:'<path d="M20 4C8 4 4 8 4 16c0 3 2 4 5 4 9 0 11-8 11-16zM4 20c4-6 7-8 12-11"/>',close:'<path d="M5 5l14 14M19 5 5 19"/>',checklist:'<path d="M9 6h12M9 12h12M9 18h12M3 6l1 1 2-2M3 12l1 1 2-2M3 18l1 1 2-2"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',palette:'<circle cx="12" cy="12" r="9"/><circle cx="8" cy="9" r="1"/><circle cx="14" cy="7" r="1"/><circle cx="17" cy="13" r="1"/><path d="M12 21a3 3 0 0 1 0-6h1"/>',printer:'<path d="M6 9V3h12v6M6 18H3v-8h18v8h-3M6 15h12v6H6z"/>'};
const ico=(name,cl='')=>`<span class="icon ${cl}" aria-hidden="true"><svg viewBox="0 0 24 24">${icons[name]||icons.leaf}</svg></span>`;
const nav=[['accueil','home','Accueil'],['projets','projects','Projets'],['cours','course','Cours'],['carnet','journal','Mon carnet'],['atelier','atelier','Mon atelier']];
const seasons={automne:{label:'Automne',hero:'hero-autumn',heading:'La poésie des papiers',sub:'Empreintes, souvenirs et créations à feuilleter au fil des saisons.',project:'feuilles-du-temps'},hiver:{label:'Hiver',hero:'hero-winter',heading:'Histoires d’hiver',sub:'Des papiers doux, du relief, des détails givrés et des cadeaux à créer.',project:'tags-hiver'},printemps:{label:'Printemps',hero:'hero-spring',heading:'L’atelier s’éveille',sub:'Fleurs, herbiers, tampons délicats et papiers lumineux.',project:'carte-sauge'},ete:{label:'Été',hero:'hero-summer',heading:'Carnets d’évasion',sub:'Des escapades aux couleurs du soleil, à conserver et à raconter.',project:'album-voyage'}};
const defaultState=()=>({season:'automne',favorites:[],progress:{},lastCourse:'tamponnage',notes:{},journal:[],inventory:[],swatches:[],createdAt:new Date().toISOString()});
let state=defaultState(),database=null,storageMode='indexeddb',filter={q:'',family:'tous',category:'tous',season:'toutes',projectsTab:'projets',atelierTab:'materiel',onlyFav:false},stepChoice={},draft=null,editingType=null,installPrompt=null,toastTimer=null;
function toast(s){const el=$('#toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3300)}
function openDatabase(){return new Promise((resolve,reject)=>{if(!('indexedDB'in window)){reject(new Error('IndexedDB absent'));return}const req=indexedDB.open('atelier-des-papiers',1);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains('data'))db.createObjectStore('data')};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function readState(){return new Promise((resolve,reject)=>{const tx=database.transaction('data','readonly'),req=tx.objectStore('data').get('main');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function writeState(snapshot){return new Promise((resolve,reject)=>{const tx=database.transaction('data','readwrite');tx.objectStore('data').put(snapshot,'main');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function persist(){try{if(database)await writeState(state);else if(storageMode==='localStorage')localStorage.setItem('atelier-des-papiers-data',JSON.stringify(state))}catch(err){console.error('Sauvegarde',err);toast('Sauvegarde impossible. Pense à exporter tes données.')}}
async function boot(){try{database=await openDatabase();const saved=await readState();if(saved)state={...defaultState(),...saved}}catch(err){console.warn('IndexedDB inaccessible',err);database=null;storageMode='localStorage';try{let saved=JSON.parse(localStorage.getItem('atelier-des-papiers-data')||'null');if(saved)state={...defaultState(),...saved}}catch{}}if(!seasons[state.season])state.season='automne';render();if('serviceWorker'in navigator && location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(console.warn)}
function route(){let bits=decodeURIComponent((location.hash||'#/accueil').replace(/^#\/?/,'')).split('/').filter(Boolean);return{page:nav.some(n=>n[0]===bits[0])?bits[0]:'accueil',id:bits[1]||null}}
function go(page,id){const hash=`#/${page}${id?'/'+id:''}`;if(location.hash===hash)render();else location.hash=hash;window.scrollTo({top:0,behavior:'instant'})}
function render(){document.body.dataset.season=state.season;const r=route(),which=r.page;const body=renderPage(r);$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><a href="#/accueil" class="brand"><img class="brand-mark" src="./icons/icon.svg" alt=""><span><span class="brand-name">L’Atelier<br>des Papiers</span><span class="brand-sub">créer • apprendre • rêver</span></span></a><nav class="nav-stack" aria-label="Navigation principale">${nav.map(([p,i,t])=>`<button class="nav-link ${which===p?'active':''}" data-action="navigate" data-page="${p}" ${which===p?'aria-current="page"':''}>${ico(i)}${t}</button>`).join('')}</nav><div class="sidebar-note"><strong>Un atelier pour soi</strong>Des idées à collectionner, des gestes à maîtriser et des souvenirs à créer.<div style="margin-top:13px"><button class="btn btn-outline small-btn" data-action="release">${ico('info')} Nouveautés V${D.version}</button></div></div><div class="sidebar-foot">Créations originales • Données privées sur cet appareil</div></aside><main class="maincol"><header class="topbar"><div class="topbar-left"><span class="brand-mini">✳ L’Atelier des Papiers</span><span class="loc-hint">/ ${esc(which==='accueil'?'Un monde de papier':nav.find(x=>x[0]===which)?.[2]||'')}</span></div><div class="topbar-right"><select class="season-switch" id="season-switch" aria-label="Choisir l’ambiance de saison">${Object.entries(seasons).map(([k,s])=>`<option value="${k}" ${state.season===k?'selected':''}>${esc(s.label)}</option>`).join('')}</select><button class="icon-btn" data-action="release" title="Nouveautés de l’application" aria-label="Nouveautés de l’application">${ico('info')}</button></div></header><div id="page-content">${body}</div><footer class="footer"><span>L’Atelier des Papiers • Une création à la fois</span><span>Sauvegarde locale · V${D.version}</span></footer></main></div><nav class="bottom-nav" aria-label="Navigation mobile">${nav.map(([p,i,t])=>`<button class="bottom-item ${which===p?'active':''}" data-action="navigate" data-page="${p}" ${which===p?'aria-current="page"':''}>${ico(i)}<span>${esc(t)}</span></button>`).join('')}</nav>`}
function renderPage(r){if(r.page==='accueil')return home();if(r.page==='cours')return r.id?courseDetail(r.id):courseCatalog();if(r.page==='projets')return r.id?projectDetail(r.id):projectCatalog();if(r.page==='carnet')return journalPage();if(r.page==='atelier')return atelierPage();return home()}
function sectionHead(title,subtitle,buttonText,page){return `<div class="section-head"><div><h2>${title}</h2>${subtitle?`<p class="section-sub">${subtitle}</p>`:''}</div>${buttonText?`<button class="text-link" style="background:none;border-top:0;border-left:0;border-right:0" data-action="navigate" data-page="${page}">${buttonText} →</button>`:''}</div>`}
function hero(){const s=seasons[state.season];return `<section class="hero"><div class="hero-copy"><span class="eyebrow">LE CARNET DE SAISON · ${esc(s.label)}</span><h1>${esc(s.heading)}</h1><p>${esc(s.sub)}</p><div class="hero-actions"><button class="btn" data-action="navigate" data-page="projets" data-id="${s.project}">Découvrir le projet ${ico('next')}</button><button class="btn btn-outline" data-action="navigate" data-page="cours">Explorer les cours</button></div></div><div class="hero-img" role="img" aria-label="Collage de papiers, photographie et tag dans les tons de la saison" style="background-image:url('${img(s.hero)}')"></div></section>`}
function favoritesId(type,id){return `${type}:${id}`}
function isFav(type,id){return state.favorites.includes(favoritesId(type,id))}
function card(item,type){const favor=isFav(type,item.id);const family=type==='cours'?D.families.find(f=>f.id===item.family)?.label:item.category;return `<article class="tile"><div class="image-wrap"><img class="tile-img" src="${img(item.image)}" alt="Illustration originale du projet ${esc(item.title)}" loading="lazy"><button class="icon-btn floating-heart ${favor?'active':''}" data-action="favorite" data-kind="${type}" data-id="${esc(item.id)}" title="${favor?'Retirer des favoris':'Ajouter aux favoris'}" aria-label="${favor?'Retirer':'Ajouter'} ${esc(item.title)} ${favor?'des':'aux'} favoris">${ico('heart')}</button></div><div class="tile-body"><span class="tinytag">${esc(family||'Atelier')}</span><h3 class="tile-title">${esc(item.title)}</h3><p class="tile-desc">${esc(item.subtitle||item.description)}</p><div class="tile-meta"><span>${esc(item.level)}</span><span class="dot"></span><span>${esc(item.duration)}</span></div><div class="tile-actions"><button class="tile-open" data-action="navigate" data-page="${type}" data-id="${esc(item.id)}">${type==='cours'?'Ouvrir le cours':'Voir le projet'} →</button>${type==='cours'?`<span class="small muted">${progressCount(item.id)}/${item.steps.length} étapes</span>`:`<span class="tag-ribbon">${esc(item.season||'Toutes saisons')}</span>`}</div></div></article>`}
function home(){const season=state.season;const last=D.courses.find(c=>c.id===state.lastCourse)||D.courses[0];const featured=D.projects.filter(p=>p.season===season||p.season==='toutes').slice(0,3);const cards=featured.length>=3?featured:[...featured,...D.projects.filter(p=>!featured.includes(p))].slice(0,3);return `${hero()}<section class="section">${sectionHead('À découvrir dans l’atelier','Des idées pour apprendre, tester et créer.', 'Tous les projets','projets')}<div class="grid grid-3">${cards.map(p=>card(p,'projets')).join('')}</div></section><section class="section">${sectionHead('Ma progression','Retrouve le dernier geste étudié et avance à ton rythme.','Tous les cours','cours')}<div class="callout" style="display:flex;gap:18px;align-items:center;justify-content:space-between;flex-wrap:wrap"><div><span class="eyebrow">REPRENDRE LE FIL</span><h3 style="margin:8px 0">${esc(last.title)}</h3><p class="muted small">${progressCount(last.id)} étape(s) terminée(s) sur ${last.steps.length}</p><div class="progress-track" style="width:min(340px,70vw)"><div class="progress-fill" style="width:${Math.round(progressCount(last.id)/last.steps.length*100)}%"></div></div></div><button class="btn" data-action="navigate" data-page="cours" data-id="${last.id}">Reprendre le cours ${ico('next')}</button></div></section><section class="section">${sectionHead('La bibliothèque des techniques','Un parcours conseillé, mais chaque cours s’ouvre librement.','Explorer','cours')}<div class="grid grid-3">${D.courses.slice(0,3).map(c=>card(c,'cours')).join('')}</div></section><section class="section">${sectionHead('Petites idées, grandes histoires','Quelques portes d’entrée pour développer ton style.')}<div class="feature-strip"><div class="feature-card"><span class="feature-icon">${ico('tag')}</span><div><strong>L’art des tags</strong><p>Petites créations aux encres, tampons et matières patinées.</p><button class="tile-open" data-action="navigate" data-page="projets" data-id="tag-vintage">Créer un tag →</button></div></div><div class="feature-card"><span class="feature-icon">${ico('layers')}</span><div><strong>Junk journal</strong><p>Collages, fragments de mémoire et papiers anciens.</p><button class="tile-open" data-action="navigate" data-page="cours" data-id="junk-journal">Découvrir →</button></div></div><div class="feature-card"><span class="feature-icon">${ico('journal')}</span><div><strong>Mon carnet créatif</strong><p>Garde la trace de tes essais avec photos et annotations.</p><button class="tile-open" data-action="navigate" data-page="carnet">Ouvrir mon carnet →</button></div></div></div></section>`}
function searchToolbar(type){let project=type==='projets';return `<div class="filterbar"><label class="searchbox">${ico('search')}<span class="sr-only">Rechercher</span><input id="catalog-search" autocomplete="off" type="search" placeholder="Rechercher un ${project?'projet':'cours'}, une technique…" value="${esc(filter.q)}"></label>${project?`<select id="category-filter" class="filterselect" aria-label="Catégorie de projet"><option value="tous">Tous les univers</option>${[...new Set(D.projects.map(p=>p.category))].map(c=>`<option ${filter.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select><select id="season-filter" class="filterselect" aria-label="Saison"><option value="toutes">Toutes saisons</option>${Object.entries(seasons).map(([k,s])=>`<option value="${k}" ${filter.season===k?'selected':''}>${esc(s.label)}</option>`).join('')}</select>`:`<select id="family-filter" class="filterselect" aria-label="Famille de techniques"><option value="tous">Toutes les techniques</option>${D.families.map(f=>`<option value="${f.id}" ${filter.family===f.id?'selected':''}>${esc(f.label)}</option>`).join('')}</select>`}<label class="chip" style="display:flex;align-items:center;gap:6px;cursor:pointer"><input type="checkbox" id="fav-filter" ${filter.onlyFav?'checked':''}> Favoris</label></div>`}
function catalogCards(type){const q=filter.q.trim().toLocaleLowerCase('fr');const arr=(type==='cours'?D.courses:D.projects).filter(i=>(!q||`${i.title} ${i.subtitle||''} ${i.description} ${i.category||''}`.toLocaleLowerCase('fr').includes(q)) &&(!filter.onlyFav||isFav(type,i.id)) && (type==='cours'?(filter.family==='tous'||i.family===filter.family):((filter.category==='tous'||i.category===filter.category)&&(filter.season==='toutes'||i.season===filter.season||i.season==='toutes'))));return arr.length?`<div class="grid grid-3">${arr.map(i=>card(i,type)).join('')}</div>`:`<div class="empty">${ico('search')}<h3>Aucun résultat</h3><p>Essaie un autre mot-clé ou modifie les filtres.</p><button class="btn btn-soft" data-action="reset-filter">Effacer les filtres</button></div>`}
function courseCatalog(){return `<div class="eyebrow">L'ÉCOLE DES PAPIERS</div><h1 class="page-title">Apprendre, expérimenter, créer.</h1><p class="lede">Huit cours progressifs, des gestes expliqués avec précision, des conseils et des exercices. Tu peux suivre l’ordre proposé ou choisir librement une technique.</p><div class="callout"><span class="eyebrow">PARCOURS CONSEILLÉ</span><p style="margin-top:8px">Commence par les tampons et les encres, explore les reliefs, puis fabrique une carte, un album ou une page de junk journal.</p></div>${searchToolbar('cours')}<div id="catalog-results">${catalogCards('cours')}</div>`}
function projectCatalog(){return `<div class="eyebrow">CRÉER AU FIL DES SAISONS</div><h1 class="page-title">La galerie des projets</h1><p class="lede">Tags, pages photo, cartes, carnets et mini-albums. Choisis une réalisation guidée ou feuillette les inspirations pour inventer la tienne.</p><div class="section-tabs"><button class="tab ${filter.projectsTab==='projets'?'active':''}" data-action="projects-tab" data-tab="projets">Projets guidés</button><button class="tab ${filter.projectsTab==='inspirations'?'active':''}" data-action="projects-tab" data-tab="inspirations">Inspirations & sketches</button></div>${filter.projectsTab==='projets'?`${searchToolbar('projets')}<div id="catalog-results">${catalogCards('projets')}</div>`:`<div class="grid grid-2">${D.inspirations.map(i=>`<article class="tile"><img src="${img(i.image)}" class="tile-img" alt="Illustration du thème ${esc(i.title)}"><div class="tile-body"><h3 class="tile-title">${esc(i.title)}</h3><p class="tile-desc">${esc(i.subtitle)}</p><button class="tile-open" data-action="inspiration-filter" data-category="${esc(i.filter)}">Voir les projets associés →</button></div></article>`).join('')}</div><section class="section">${sectionHead('Petite bibliothèque de sketches','Des compositions de départ à personnaliser librement.')}<div class="grid grid-3">${['Photo principale & légende','Composition en diagonale','Trois tags en série'].map((t,i)=>`<div class="panel"><div class="sketch-preview" aria-label="Schéma de mise en page"><div></div><div></div><div class="wide"></div></div><h3 style="margin-top:13px">${t}</h3><p class="small muted">Sketch ${String(i+1).padStart(2,'0')} • À interpréter selon ton matériel.</p></div>`).join('')}</div></section>`}`}
function progressCount(id){return (state.progress[id]||[]).length}
function detailHeader(kind,id){return `<div class="breadcrumbs"><button data-action="navigate" data-page="${kind}">${kind==='cours'?'Tous les cours':'Tous les projets'}</button>${ico('next')}<span>Fiche détaillée</span></div>`}
function projectDetail(id){const p=D.projects.find(x=>x.id===id);if(!p)return notFound('projets');if(p.tutorial)return projectTutorialDetail(p);return `${detailHeader('projets',id)}<div class="detail-hero"><div><span class="eyebrow">${esc(p.category)} · ${esc(p.season==='toutes'?'Toutes saisons':seasons[p.season]?.label||p.season)}</span><h1>${esc(p.title)}</h1><p>${esc(p.description)}</p><div class="chips"><span class="chip">${esc(p.level)}</span><span class="chip">${esc(p.duration)}</span></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn" data-action="start-project" data-id="${p.id}">${ico('plus')} Ajouter à mon carnet</button><button class="btn btn-outline" data-action="favorite" data-kind="projets" data-id="${p.id}">${ico('heart')} ${isFav('projets',p.id)?'Dans mes favoris':'Favori'}</button></div></div><img class="detail-hero-img" src="${img(p.image)}" alt="Illustration de ${esc(p.title)}"></div><div class="detail-content"><div><section class="panel"><span class="eyebrow">RÉALISATION GUIDÉE</span><h2>Pas à pas</h2><p class="muted small">Une première trame à compléter par les photographies détaillées de l’atelier.</p><ol class="article-text" style="padding-left:21px;margin-top:17px">${p.steps.map(s=>`<li style="margin-bottom:12px">${esc(s)}</li>`).join('')}</ol></section><section class="panel"><h2>Les techniques liées</h2><div class="grid grid-2" style="margin-top:18px">${p.courseIds.map(c=>{const cr=D.courses.find(x=>x.id===c);return cr?`<button class="btn btn-soft" data-action="navigate" data-page="cours" data-id="${cr.id}">${ico('course')} ${esc(cr.title)}</button>`:''}).join('')}</div></section></div><aside><section class="panel"><h3>Préparer son matériel</h3><ul class="material-list">${p.materials.map(s=>`<li><input class="tick" type="checkbox" aria-label="J’ai : ${esc(s)}"><span>${esc(s)}</span></li>`).join('')}</ul></section><section class="panel"><h3>Ta version sera unique</h3><p class="small muted">Ajoute ce projet à ton carnet pour modifier le titre, garder tes photos et écrire tes propres notes.</p><button class="btn" style="margin-top:13px;width:100%" data-action="start-project" data-id="${p.id}">Commencer ma création</button></section></aside></div>`}
function projectTutorialDetail(p){
 const done=state.progress['project:'+p.id]||[];
 const pct=Math.round(done.length/p.steps.length*100);
 const photoURL=(file)=>`./assets/${encodeURIComponent(file)}`;
 return `${detailHeader('projets',p.id)}
 <section class="tag-tutorial-intro"><div class="tag-intro-copy"><span class="eyebrow">L'ART DES TAGS · ATELIER PHOTOGRAPHIQUE</span><h1>${esc(p.title)}</h1><p>${esc(p.description)}</p><div class="chips"><span class="chip">${esc(p.level)}</span><span class="chip">${esc(p.duration)}</span><span class="chip">${done.length}/${p.steps.length} étapes réalisées</span></div><div class="tag-intro-actions"><a class="btn" href="${esc(p.pattern)}" target="_blank" rel="noopener noreferrer">${ico('printer')} Télécharger le patron PDF</a><button class="btn btn-outline" data-action="start-project" data-id="${esc(p.id)}">${ico('camera')} Ajouter à mon carnet</button><button class="btn btn-outline" data-action="favorite" data-kind="projets" data-id="${esc(p.id)}">${ico('heart')} ${isFav('projets',p.id)?'Dans mes favoris':'Favori'}</button></div></div><button class="tag-cover" data-action="zoom-tag-photo" data-id="${esc(p.id)}" data-photo="${esc(p.coverPhoto)}" data-caption="Tag terminé"><img src="${photoURL(p.coverPhoto)}" alt="Tag vintage fini, motif botanique et ficelle"/><span>Voir le résultat en grand ${ico('next')}</span></button></section>
 <div class="tag-tutorial-layout"><div class="tag-tutorial-main"><section class="panel"><span class="eyebrow">LE PROJET DE A À Z</span><h2>Neuf gestes pour un tag patiné</h2><p class="muted small" style="margin-top:8px">Les photographies sont des illustrations pédagogiques créées pour l'atelier, et non des photos de gestes réellement exécutés. Suis les dimensions et les consignes écrites pour travailler précisément.</p><div class="progress-track" style="margin-top:18px"><div class="progress-fill" style="width:${pct}%"></div></div><p class="small muted">${done.length} étape(s) cochée(s) sur ${p.steps.length} · Tu peux avancer à ton rythme.</p></section>
 <div class="tag-stages">${p.steps.map((st,i)=>`<article class="tag-stage ${done.includes(i)?'tag-stage-done':''}" id="tag-etape-${i+1}"><button class="tag-stage-photo" data-action="zoom-tag-photo" data-id="${esc(p.id)}" data-photo="${esc(st.photo)}" data-caption="Étape ${i+1} : ${esc(st.caption)}" aria-label="Agrandir la photographie de l'étape ${i+1}"><img loading="lazy" src="${photoURL(st.photo)}" alt="${esc(st.caption)}"><span>${ico('search')} Agrandir</span></button><div class="tag-stage-text"><div class="tag-stage-kicker">ÉTAPE ${String(i+1).padStart(2,'0')} · ${esc(st.duration)}</div><h3>${esc(st.title)}</h3><p class="article-text">${esc(st.body)}</p><div class="tag-tip"><strong>${ico('leaf')} Le conseil</strong><p>${esc(st.tip)}</p></div><div class="tag-pitfall"><strong>${ico('info')} À éviter</strong><p>${esc(st.mistake)}</p></div><button class="btn ${done.includes(i)?'btn-soft':'btn-outline'} small-btn" data-action="toggle-tag-step" data-id="${esc(p.id)}" data-index="${i}">${ico('check')} ${done.includes(i)?'Étape réalisée':'Marquer comme réalisée'}</button></div></article>`).join('')}</div>
 <section class="panel"><span class="eyebrow">POUR ALLER PLUS LOIN</span><h2>Trois variantes à imaginer</h2><ul class="material-list">${(p.variants||[]).map(v=>`<li>${ico('leaf')}<span>${esc(v)}</span></li>`).join('')}</ul><button class="btn" data-action="start-project" data-id="${esc(p.id)}" style="margin-top:16px">${ico('camera')} Photographier ma création</button></section>
 <section class="panel"><h2>Les techniques à réviser</h2><div class="grid grid-2" style="margin-top:18px">${p.courseIds.map(id=>{const cr=D.courses.find(c=>c.id===id);return cr?`<button class="btn btn-soft" data-action="navigate" data-page="cours" data-id="${esc(cr.id)}">${ico('course')} ${esc(cr.title)}</button>`:''}).join('')}</div></section></div>
 <aside class="tag-sidebar"><section class="panel"><span class="eyebrow">À IMPRIMER</span><h3>Patron à taille réelle</h3><div class="tag-pattern-silhouette"><svg viewBox="0 0 140 200" aria-label="Gabarit du tag : 7 cm de large et 12 cm de haut"><path d="M18 20 H122 L138 36 V183 H2 V36 Z" fill="#e9d9bc" stroke="#836e53" stroke-width="2"/><circle cx="70" cy="20" r="5" fill="white" stroke="#836e53" stroke-width="1.5"/></svg></div><p class="small muted">${esc(p.patternDescription)}</p><a class="btn" style="width:100%;text-align:center" href="${esc(p.pattern)}" target="_blank" rel="noopener noreferrer">${ico('download')} Patron PDF A4</a></section>
 <section class="panel"><span class="eyebrow">AVANT DE CRÉER</span><h3>Mon matériel</h3><p class="small muted" style="margin-top:8px">Coche ce que tu as préparé. Les cases sont temporaires ; la progression des étapes est, elle, sauvegardée.</p><ul class="material-list">${p.materials.map(m=>`<li><input type="checkbox" class="tick" aria-label="J'ai : ${esc(m)}"><span>${esc(m)}</span></li>`).join('')}</ul></section>
 <section class="panel"><h3>Les pièges classiques</h3><ul class="material-list">${p.mistakes.map(m=>`<li>${ico('info')}<span>${esc(m)}</span></li>`).join('')}</ul></section>
 <section class="panel"><h3>Sources et inspirations</h3><p class="small muted">Technique vérifiée à partir des ressources officielles Ranger. Ce tutoriel est une création indépendante.</p><div class="source-list">${p.sources.map(s=>`<a target="_blank" rel="noopener noreferrer" href="${esc(s.url)}">${esc(s.label)} ↗</a>`).join('')}</div></section></aside></div>`;
}
function notFound(page){return `<div class="empty"><h2>Cette fiche n’existe pas</h2><button class="btn" data-action="navigate" data-page="${page}">Retour à la bibliothèque</button></div>`}
function stepDiagram(course,index,photoIndex){let base=course.image, isFirst=course.id==='tamponnage'; const n=(index+photoIndex)%4; let shapes='';if(isFirst){if(index===0||index===1){shapes='<rect x="30" y="31" width="114" height="63" rx="5" fill="#ddcfc0" stroke="#897968"/><path d="M52 74h70M52 64h70M52 54h70" stroke="#8f776b" stroke-width="2" opacity=".5"/><rect x="67" y="43" width="42" height="42" rx="4" stroke="#a57e5d" stroke-width="3" fill="#f2e7d2"/><path d="M83 73q12-25 15-18M87 66q-15-15-17-7M94 58q16-10 17-1" fill="none" stroke="#79866c" stroke-width="3"/>'}else if(index===2){shapes='<rect x="32" y="28" width="108" height="69" rx="6" fill="#d5b89a" stroke="#8e6e59" stroke-width="3"/><rect x="43" y="38" width="86" height="49" rx="5" fill="#af7355" opacity=".85"/><rect x="148" y="44" width="57" height="45" rx="4" fill="#f1e4d0" stroke="#967d65"/><path d="M171 79v-20" stroke="#6a8770" stroke-width="4"/><path d="M165 73l-11-13M173 70l12-16" stroke="#6a8770" stroke-width="3"/>'}else if(index===3){shapes='<rect x="37" y="17" width="159" height="105" rx="5" fill="#fff8ea" stroke="#cebba5"/><rect x="68" y="26" width="99" height="78" rx="4" fill="#d4e3df" fill-opacity=".75" stroke="#6b8580" stroke-dasharray="5 3" stroke-width="3"/><path d="M115 84V43M112 69q-26-17-31-2M116 58q24-19 30-10" fill="none" stroke="#71876a" stroke-width="4"/>'}else if(index===4){shapes=[44,107,170].map((x,i)=>`<rect x="${x}" y="42" width="50" height="78" fill="#faf0de" stroke="#a18e79"/><path d="M${x+25} 106V62M${x+25} 78q-17-12-18-4M${x+25} 85q14-16 20-8" stroke="#687c60" stroke-width="${i===1?8:i===2?2:4}" fill="none" opacity="${i===2?.4:.85}"/>`).join('')}else{shapes='<path d="M73 18h88l24 23v92H49V41z" fill="#ead5b3" stroke="#b39879" stroke-width="2"/><circle cx="116" cy="40" r="7" fill="white" stroke="#a98c72" stroke-width="3"/><path d="M116 126q-18-60 2-88m-2 55q-36-24-37-6m39-15q35-22 34-8" stroke="#647b5d" stroke-width="4" fill="none"/>'}}else{shapes=`<rect x="42" y="22" width="152" height="105" rx="6" fill="#fbf1df" stroke="#bea88d" stroke-width="3"/><path d="M72 105Q91 37 171 82" stroke="#a57a59" stroke-width="${6+n*4}" fill="none" opacity=".6"/><circle cx="${85+n*16}" cy="${65+n*6}" r="22" fill="${['#c0a080','#889c8b','#b59a79','#8795a2'][n]}" opacity=".65"/><path d="M142 115q-14-36 2-70m-1 46q-24-15-24-6m26-17q19-21 26-11" fill="none" stroke="#6b8669" stroke-width="3"/>`};return `<svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Schéma original de démonstration : ${esc(course.steps[index].title)}" viewBox="0 0 240 145" style="width:100%;display:block;background:#eee4d5"><rect width="240" height="145" fill="#eee4d5"/><path d="M0 18h240M0 129h240" stroke="#d8c9b5" opacity=".6"/>${shapes}<rect x="5" y="5" width="38" height="19" rx="3" fill="#7b6957"/><text x="24" y="18" text-anchor="middle" font-size="10" font-family="Arial" fill="white">${index+1}.${photoIndex+1}</text></svg>`}
function courseDetail(id){const c=D.courses.find(x=>x.id===id);if(!c)return notFound('cours');const index=Math.min(stepChoice[id]??state.lastStep?.[id]??0,c.steps.length-1),st=c.steps[index],done=(state.progress[id]||[]);const pct=Math.round(done.length/c.steps.length*100);return `${detailHeader('cours',id)}<div class="detail-hero"><div><span class="eyebrow">COURS ${String(c.number).padStart(2,'0')} · ${esc(D.families.find(f=>f.id===c.family)?.label||'')}</span><h1>${esc(c.title)}</h1><p style="font-family:var(--font-serif);font-style:italic;font-size:1.14rem;margin:0 0 9px">${esc(c.subtitle)}</p><p class="muted">${esc(c.description)}</p><div class="chips"><span class="chip">${esc(c.level)}</span><span class="chip">${esc(c.duration)}</span><span class="chip">${pct}% parcouru</span></div><button class="btn btn-outline" data-action="favorite" data-kind="cours" data-id="${c.id}">${ico('heart')} ${isFav('cours',c.id)?'Dans mes favoris':'Ajouter aux favoris'}</button></div><img class="detail-hero-img" src="${img(c.image)}" alt="Illustration artistique pour ${esc(c.title)}"></div><div class="detail-content"><div><section class="panel"><span class="eyebrow">LE FIL DE LA LEÇON</span><h2>Apprendre le geste</h2><p class="muted small" style="margin-top:7px">Étape ${index+1} sur ${c.steps.length} · ${esc(st.time||c.duration)}</p><div class="stepbar">${c.steps.map((s,i)=>`<button class="stepdot ${i===index?'selected':done.includes(i)?'completed':''}" data-action="step" data-course="${c.id}" data-index="${i}" aria-label="Aller à l’étape ${i+1} : ${esc(s.title)}" title="${esc(s.title)}"></button>`).join('')}</div><h3 class="step-name">${esc(st.title)}</h3><p class="article-text" style="margin-top:13px">${esc(st.body)}</p><div class="step-visuals">${(st.views||[]).map((view,vi)=>`<button class="visual" data-action="zoom-diagram" data-course="${c.id}" data-step="${index}" data-view="${vi}" aria-label="Agrandir le schéma ${vi+1}">${stepDiagram(c,index,vi)}<span>${esc(view)}<small class="visual-mark">Schéma de démonstration • agrandir</small></span></button>`).join('')}</div><p class="muted small">Les schémas originaux servent de repères dans cette première version. Des photographies rapprochées des gestes remplaceront ces vues lors de l’enrichissement du cours.</p>${st.tip?`<div class="hint"><strong>Le conseil de l’atelier</strong><br>${esc(st.tip)}</div>`:''}${st.mistake?`<div class="hint warning"><strong>À éviter</strong><br>${esc(st.mistake)}</div>`:''}<div class="step-controls"><button class="btn btn-outline small-btn" data-action="prev-step" data-course="${id}" ${index===0?'disabled':''}>${ico('back')} Précédent</button><button class="btn ${done.includes(index)?'btn-soft':''} small-btn" data-action="complete-step" data-course="${id}" data-index="${index}">${ico('check')} ${done.includes(index)?'Étape réalisée':'Marquer comme réalisée'}</button><button class="btn btn-outline small-btn" data-action="next-step" data-course="${id}" ${index===c.steps.length-1?'disabled':''}>Suivant ${ico('next')}</button></div><div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div><p class="small muted">${done.length} / ${c.steps.length} étapes terminées</p></section><section class="panel"><span class="eyebrow">METTRE EN PRATIQUE</span><h2>L’exercice de l’atelier</h2><p class="article-text" style="margin-top:12px">${esc(c.challenge)}</p><div class="callout"><strong>Résultat attendu</strong><p style="margin-top:6px">${esc(c.outcome)}</p></div><button class="btn" data-action="course-to-journal" data-course="${id}">${ico('camera')} Enregistrer mon essai</button></section><section class="panel"><h3>Mes notes de cours</h3><p class="small muted" style="margin:6px 0 12px">Idées, questions, références d’encres… Tes notes restent enregistrées sur cet appareil.</p><textarea class="textarea" id="course-note" data-course="${id}" placeholder="Ce que j’ai découvert, envie d’essayer…">${esc(state.notes[id]||'')}</textarea><button class="btn btn-soft small-btn" style="margin-top:8px" data-action="save-note" data-course="${id}">Enregistrer ma note</button></section></div><aside><section class="panel"><span class="eyebrow">AVANT DE COMMENCER</span><h3>Préparer le matériel</h3><ul class="material-list">${c.materials.map(m=>`<li><input type="checkbox" class="tick" aria-label="J’ai : ${esc(m)}"><span>${esc(m)}</span></li>`).join('')}</ul><div class="hint" style="margin-top:18px"><strong>Préparation</strong><br>${esc(c.preparation)}</div></section><section class="panel"><h3>Les erreurs fréquentes</h3><ul class="material-list">${c.mistakes.map(m=>`<li>${ico('info')}<span>${esc(m)}</span></li>`).join('')}</ul></section>${c.sources.length?`<section class="panel"><h3>Pour approfondir</h3><div class="source-list">${c.sources.map(s=>`<a target="_blank" rel="noopener noreferrer" href="${esc(s.url)}">${esc(s.label)} ↗</a>`).join('')}</div></section>`:''}</aside></div>`}
function journalPage(){const list=[...state.journal].sort((a,b)=>(b.updatedAt||b.date||'').localeCompare(a.updatedAt||a.date||''));return `<div class="eyebrow">LES PAGES DE MON CARNET</div><h1 class="page-title">Mes créations, mes souvenirs.</h1><p class="lede">Conserve tes réalisations, tes essais et tes idées. Chaque fiche peut être modifiée, enrichie de cinq photos et retrouvée plus tard.</p><div class="filterbar"><button class="btn" data-action="new-entry">${ico('plus')} Nouvelle création</button><button class="btn btn-outline" data-action="export">${ico('download')} Sauvegarder mes données</button></div>${list.length?`<div class="grid grid-2">${list.map(entry=>`<article class="entry-card"><img class="entry-thumb" src="${safePhoto(entry.photos?.[0])||img(D.projects.find(x=>x.id===entry.projectId)?.image||'journal')}" alt="${esc(entry.title)}"><div class="entry-body"><span class="tinytag">${esc(entry.type||'Création personnelle')}</span><h3>${esc(entry.title||'Sans titre')}</h3><p class="muted small">${esc(entry.date||'')} · ${esc(entry.status||'En cours')}</p><p class="small" style="max-height:3.2em;overflow:hidden">${esc(entry.description||entry.notes||'')}</p><div class="entry-actions"><button class="btn btn-soft small-btn" data-action="edit-entry" data-id="${esc(entry.id)}">${ico('edit')} Modifier</button><button class="btn btn-quiet small-btn" data-action="delete-entry" data-id="${esc(entry.id)}">${ico('trash')} Supprimer</button></div></div></article>`).join('')}</div>`:`<div class="empty">${ico('camera')}<h3>Une première page blanche</h3><p>Ajoute ton prochain tag, une carte, une page photo ou une idée à essayer. Tu pourras y revenir pour compléter les notes et les photos.</p><button class="btn" data-action="new-entry">Créer ma première fiche</button></div>`}`}
const inventoryCats=['Tampons','Encres','Papiers','Dies & découpes','Pochoirs','Outils','Embossage','Embellissements','Autres'];
function atelierPage(){let t=filter.atelierTab;return `<div class="eyebrow">MA PETITE MERCERIE DU PAPIER</div><h1 class="page-title">Mon atelier personnel</h1><p class="lede">Retrouve les fournitures que tu possèdes, photographie tes essais de couleurs et garde tes sauvegardes à portée de main.</p><div class="section-tabs"><button class="tab ${t==='materiel'?'active':''}" data-action="atelier-tab" data-tab="materiel">Matériel</button><button class="tab ${t==='nuancier'?'active':''}" data-action="atelier-tab" data-tab="nuancier">Nuancier</button><button class="tab ${t==='sauvegardes'?'active':''}" data-action="atelier-tab" data-tab="sauvegardes">Sauvegardes</button></div>${t==='materiel'?inventoryPage():t==='nuancier'?swatchesPage():backupPage()}`}
function inventoryPage(){return `<div class="section-head"><div><h2>Mes fournitures</h2><p class="section-sub">${state.inventory.length} référence(s) enregistrée(s)</p></div><button class="btn" data-action="new-inventory">${ico('plus')} Ajouter</button></div>${state.inventory.length?`<div class="inventory-grid">${[...state.inventory].sort((a,b)=>a.category.localeCompare(b.category)||a.name.localeCompare(b.name)).map(i=>`<div class="item-card"><span class="tinytag">${esc(i.category)}</span><h3>${esc(i.name)}</h3><p class="meta">${esc(i.brand||'Sans marque')} ${i.color?'· '+esc(i.color):''}</p><p class="small muted">Quantité : ${esc(i.quantity||'1')}</p>${i.notes?`<p class="small">${esc(i.notes)}</p>`:''}<div class="item-actions"><button class="btn btn-soft small-btn" data-action="edit-inventory" data-id="${esc(i.id)}">Modifier</button><button class="btn btn-quiet small-btn" data-action="delete-inventory" data-id="${esc(i.id)}">${ico('trash')}</button></div></div>`).join('')}</div>`:`<div class="empty">${ico('atelier')}<h3>Un atelier à inventorier</h3><p>Commence par les encres, les tampons ou ta collection de papiers préférée.</p><button class="btn" data-action="new-inventory">Ajouter une fourniture</button></div>`}`}
function swatchesPage(){return `<div class="section-head"><div><h2>Mon nuancier d'encres</h2><p class="section-sub">Note les couleurs et leurs effets sur tes papiers.</p></div><button class="btn" data-action="new-swatch">${ico('plus')} Ajouter une couleur</button></div>${state.swatches.length?`<div class="inventory-grid">${state.swatches.map(s=>`<div class="item-card"><div style="height:70px;border-radius:8px;background:${/^#[0-9a-fA-F]{6}$/.test(s.color||'')?s.color:'#b4a189'};border:1px solid #ae9984"></div><span class="tinytag">${esc(s.family||'Encre')}</span><h3>${esc(s.name)}</h3><p class="small muted">${esc(s.brand||'')} ${s.paper?'· sur '+esc(s.paper):''}</p>${s.notes?`<p class="small">${esc(s.notes)}</p>`:''}<div class="item-actions"><button class="btn btn-soft small-btn" data-action="edit-swatch" data-id="${esc(s.id)}">Modifier</button><button class="btn btn-quiet small-btn" data-action="delete-swatch" data-id="${esc(s.id)}">${ico('trash')}</button></div></div>`).join('')}</div>`:`<div class="empty">${ico('palette')}<h3>Construis ton nuancier</h3><p>Choisis une encre, note sa référence et la couleur observée. Tu pourras ensuite comparer ses effets dans les cours.</p><button class="btn" data-action="new-swatch">Ajouter ma première encre</button></div>`}`}
function backupPage(){return `<div class="grid grid-2"><section class="panel"><span class="eyebrow">EXPORTER</span><h2>Conserver une copie</h2><p class="small muted" style="margin:12px 0">Télécharge un fichier JSON contenant tes créations, photographies, notes, favoris, étapes terminées et inventaire. Garde une copie ailleurs que sur ton appareil.</p><button class="btn" data-action="export">${ico('download')} Exporter mes données</button></section><section class="panel"><span class="eyebrow">IMPORTER</span><h2>Restaurer une sauvegarde</h2><p class="small muted" style="margin:12px 0">Choisis une sauvegarde précédemment exportée. La restauration remplace les données locales actuelles après confirmation.</p><label class="btn btn-outline" style="cursor:pointer">${ico('upload')} Choisir un fichier <input id="restore-file" type="file" accept=".json,application/json" style="display:none"></label></section></div><div class="hint" style="margin-top:22px"><strong>À savoir</strong><br>Cette première version ne synchronise rien entre les appareils. Les données restent dans le navigateur ou l’application installée. Une désinstallation ou un effacement des données du navigateur peut les supprimer. L’export régulier est donc essentiel.</div>`}
function modalOpen(html){$('#modal-content').innerHTML=html;const m=$('#modal');if(!m.open)m.showModal()}
function modalClose(){$('#modal').close();draft=null;editingType=null}
function modalFrame(title,body,footer){return `<div class="modal-inner"><div class="modal-head"><div><span class="eyebrow">L'ATELIER DES PAPIERS</span><h2>${esc(title)}</h2></div><button class="close-button" data-action="close-modal" aria-label="Fermer">×</button></div>${body}${footer||''}</div>`}
function entryDraftForProject(projectId){const p=D.projects.find(x=>x.id===projectId);return{id:guid(),title:p?.title||'Ma création',date:time(),status:'En cours',type:p?.category||'Création personnelle',projectId:projectId||'',description:p?.description||'',notes:'',photos:[],createdAt:new Date().toISOString()}}
function openEntry(id=null,projectId=null,courseId=null){if(id){const item=state.journal.find(e=>e.id===id);if(!item)return;draft=JSON.parse(JSON.stringify(item))}else if(projectId)draft=entryDraftForProject(projectId);else if(courseId){let c=D.courses.find(x=>x.id===courseId);draft={...entryDraftForProject(null),title:`Mon essai : ${c?.title||'Cours'}`,description:c?.challenge||'',type:'Exercice de cours'}}else draft=entryDraftForProject(null);editingType='journal';showEntryModal()}
function readDraftFields(){const form=$('#entry-form');if(!form||!draft)return;for(const k of ['title','date','type','status','description','notes'])if(form.elements[k])draft[k]=form.elements[k].value}
function showEntryModal(){modalOpen(modalFrame(draft?.createdAt&&state.journal.some(x=>x.id===draft.id)?'Modifier ma création':'Nouvelle création',`<form id="entry-form" class="form-stack"><div class="field"><label for="entry-title">Titre *</label><input class="input" id="entry-title" name="title" required maxlength="150" value="${esc(draft.title)}" placeholder="Ex. Mon premier tag vintage"></div><div class="form-grid"><div class="field"><label for="entry-date">Date</label><input class="input" type="date" id="entry-date" name="date" value="${esc(draft.date||time())}"></div><div class="field"><label for="entry-status">Avancement</label><select class="input" id="entry-status" name="status">${['En cours','Terminé','À essayer'].map(x=>`<option ${draft.status===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="field"><label for="entry-type">Type de création</label><select class="input" id="entry-type" name="type">${['Création personnelle','Tags','Carterie','Mini-albums','Pages photo','Junk journal','Mixed media','Objets en papier','Exercice de cours'].map(x=>`<option ${draft.type===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="entry-description">Présentation</label><textarea class="textarea" name="description" id="entry-description" placeholder="L’idée de départ, le projet de référence…">${esc(draft.description||'')}</textarea></div><div class="field"><label for="entry-notes">Notes personnelles</label><textarea class="textarea" name="notes" id="entry-notes" placeholder="Ce que j’ai appris, mes impressions, les changements à essayer…">${esc(draft.notes||'')}</textarea></div><div class="field"><label>Mes photographies (${(draft.photos||[]).length}/5)</label><div class="photo-strip">${(draft.photos||[]).map((p,i)=>`<div class="photo-preview"><img src="${safePhoto(p)||img('journal')}" alt="Photographie personnelle ${i+1}" data-action="open-photo" data-src="${safePhoto(p)||img('journal')}"><button type="button" class="photo-remove" data-action="remove-draft-photo" data-index="${i}" aria-label="Retirer la photo ${i+1}">×</button></div>`).join('')}</div><label class="btn btn-soft small-btn" style="cursor:pointer;margin-top:9px;${(draft.photos||[]).length>=5?'display:none':''}">${ico('camera')} Ajouter une photo <input type="file" id="entry-photos" accept="image/*" multiple style="display:none"></label><p class="small muted" style="margin-top:6px">Photos redimensionnées pour alléger les sauvegardes. Maximum cinq images par création.</p></div><div class="modal-foot"><button type="button" class="btn btn-outline" data-action="close-modal">Annuler</button><button type="submit" class="btn">${ico('check')} Enregistrer ma création</button></div></form>`))}
function openInventory(id){editingType='inventory';const item=state.inventory.find(x=>x.id===id);draft=item?{...item}:{id:guid(),category:'Encres',name:'',brand:'',color:'',quantity:'1',notes:''};modalOpen(modalFrame(id?'Modifier le matériel':'Ajouter du matériel',`<form id="inventory-form" class="form-stack"><div class="field"><label>Nom *</label><input class="input" name="name" value="${esc(draft.name)}" required maxlength="150" placeholder="Ex. Distress Oxide Walnut Stain"></div><div class="form-grid"><div class="field"><label>Catégorie</label><select class="input" name="category">${inventoryCats.map(x=>`<option ${draft.category===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Quantité</label><input class="input" type="number" name="quantity" min="1" max="999" value="${esc(draft.quantity||1)}"></div></div><div class="form-grid"><div class="field"><label>Marque</label><input class="input" name="brand" value="${esc(draft.brand||'')}" placeholder="Ranger, Simple Stories…"></div><div class="field"><label>Couleur / collection</label><input class="input" name="color" value="${esc(draft.color||'')}"></div></div><div class="field"><label>Remarques</label><textarea class="textarea" name="notes">${esc(draft.notes||'')}</textarea></div><div class="modal-foot"><button type="button" class="btn btn-outline" data-action="close-modal">Annuler</button><button class="btn" type="submit">Enregistrer</button></div></form>`))}
function openSwatch(id){editingType='swatch';const item=state.swatches.find(x=>x.id===id);draft=item?{...item}:{id:guid(),name:'',brand:'',family:'Distress Ink',paper:'Papier blanc',color:'#b78363',notes:''};modalOpen(modalFrame(id?'Modifier une couleur':'Ajouter une couleur',`<form id="swatch-form" class="form-stack"><div class="field"><label>Nom / référence *</label><input class="input" name="name" value="${esc(draft.name)}" required placeholder="Ex. Vintage Photo"></div><div class="form-grid"><div class="field"><label>Marque</label><input class="input" name="brand" value="${esc(draft.brand)}" placeholder="Ex. Ranger"></div><div class="field"><label>Famille</label><select name="family" class="input">${['Distress Ink','Distress Oxide','Archival','Pigmentaire','Dye','Autre'].map(x=>`<option ${draft.family===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="form-grid"><div class="field"><label>Couleur indicative</label><input name="color" class="input" type="color" value="${esc(draft.color||'#b78363')}" style="height:46px"></div><div class="field"><label>Support du test</label><input name="paper" class="input" value="${esc(draft.paper||'')}"></div></div><div class="field"><label>Observations</label><textarea class="textarea" name="notes" placeholder="Opacité, réactions à l’eau, rendu après séchage…">${esc(draft.notes||'')}</textarea></div><div class="modal-foot"><button type="button" class="btn btn-outline" data-action="close-modal">Annuler</button><button type="submit" class="btn">Enregistrer</button></div></form>`))}
function openRelease(){modalOpen(modalFrame(`Nouveautés · Version ${D.version}`,`<p class="small muted">Première version de découverte de L’Atelier des Papiers.</p><ul class="update-list"><li>Accueil et ambiances de printemps, été, automne et hiver.</li><li>Huit cours détaillés avec progression, conseils, exercices et schémas de démonstration.</li><li>Projets guidés : tags, carterie, albums, pages photo et junk journal.</li><li>Favoris et bibliothèque d’inspiration avec premiers sketches.</li><li>Carnet personnel éditable avec jusqu’à cinq photographies par création.</li><li>Inventaire de matériel, nuancier, export et restauration des données.</li><li>Fonctionnement PWA hors connexion après première visite en ligne.</li></ul><div class="hint"><strong>Prochaine étape éditoriale</strong><br>Réaliser les véritables séries de photographies rapprochées pour les gestes des tutoriels et compléter les gabarits imprimables.</div>`,`<div class="modal-foot"><button class="btn" data-action="close-modal">Fermer</button></div>`))}
async function downsize(file){if(!file.type.startsWith('image/'))throw Error('Le fichier choisi n’est pas une image.');const url=URL.createObjectURL(file);try{const im=new Image();await new Promise((resolve,reject)=>{im.onload=resolve;im.onerror=reject;im.src=url});const scale=Math.min(1,1440/Math.max(im.naturalWidth,im.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(im.naturalWidth*scale));canvas.height=Math.max(1,Math.round(im.naturalHeight*scale));canvas.getContext('2d').drawImage(im,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.79)}finally{URL.revokeObjectURL(url)}}
function openLightbox(source,caption=''){const d=$('#lightbox');$('#lightbox-content').innerHTML=`<div style="text-align:center"><img alt="${esc(caption)}" src="${source}">${caption?`<p style="padding:7px 0">${esc(caption)}</p>`:''}</div>`;if(!d.open)d.showModal()}
function exportData(){const payload={application:'atelier-des-papiers',format:1,exportedAt:new Date().toISOString(),data:state};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'});const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download=`atelier-des-papiers-sauvegarde-${time()}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000);toast('Sauvegarde téléchargée : garde une copie en lieu sûr.')}
async function restoreData(file){if(file.size>70*1024*1024){toast('Fichier trop volumineux (maximum 70 Mo).');return}try{const payload=JSON.parse(await file.text());if(payload.application!=='atelier-des-papiers'||payload.format!==1||!payload.data||!Array.isArray(payload.data.journal)||!Array.isArray(payload.data.inventory)||!Array.isArray(payload.data.favorites))throw Error('Format invalide');if(!confirm('Restaurer cette sauvegarde ? Toutes les données personnelles actuelles seront remplacées.'))return;const d=payload.data;state={...defaultState(),season:seasons[d.season]?d.season:'automne',favorites:d.favorites,progress:d.progress||{},lastCourse:d.lastCourse||'tamponnage',lastStep:d.lastStep||{},notes:d.notes||{},journal:d.journal,inventory:d.inventory,swatches:Array.isArray(d.swatches)?d.swatches:[]};await persist();render();toast('Sauvegarde restaurée avec succès.')}catch(err){console.error(err);toast('Impossible d’ouvrir cette sauvegarde. Vérifie le fichier.')}}
function applyCatalog(){const el=$('#catalog-results');if(el)el.innerHTML=catalogCards(route().page)}
function saveNote(id){const t=$('#course-note');if(t&&t.dataset.course===id){state.notes[id]=t.value;persist();toast('Note enregistrée.')}}
function updateStep(courseId,idx){let course=D.courses.find(x=>x.id===courseId);if(!course)return;stepChoice[courseId]=Math.max(0,Math.min(idx,course.steps.length-1));state.lastCourse=courseId;state.lastStep={...(state.lastStep||{}),[courseId]:stepChoice[courseId]};persist();render();const elem=$('.stepbar');elem?.scrollIntoView({block:'nearest',behavior:'instant'})}
function clickAction(e){const target=e.target.closest('[data-action]');if(!target)return;const a=target.dataset.action,id=target.dataset.id,course=target.dataset.course,kind=target.dataset.kind;e.preventDefault();
 if(a==='navigate'){go(target.dataset.page,id);return}
 if(a==='favorite'){const key=favoritesId(kind,id);if(isFav(kind,id))state.favorites=state.favorites.filter(x=>x!==key);else state.favorites.push(key);persist();render();toast(isFav(kind,id)?'Ajouté aux favoris.':'Retiré des favoris.');return}
 if(a==='reset-filter'){filter={...filter,q:'',family:'tous',category:'tous',season:'toutes',onlyFav:false};render();return}
 if(a==='projects-tab'){filter.projectsTab=target.dataset.tab;render();return}
 if(a==='atelier-tab'){filter.atelierTab=target.dataset.tab;render();return}
 if(a==='inspiration-filter'){filter.projectsTab='projets';filter.category=target.dataset.category;filter.q='';render();return}
 if(a==='step'){updateStep(course,Number(target.dataset.index));return}
 if(a==='prev-step'||a==='next-step'){const i=stepChoice[course]??state.lastStep?.[course]??0;updateStep(course,i+(a==='prev-step'?-1:1));return}
 if(a==='complete-step'){const i=Number(target.dataset.index);const done=state.progress[course]||[];state.progress[course]=done.includes(i)?done.filter(x=>x!==i):[...done,i].sort((x,y)=>x-y);state.lastCourse=course;persist();render();toast(state.progress[course].includes(i)?'Étape marquée comme réalisée.':'Étape remise à faire.');return}
 if(a==='save-note'){saveNote(course);return}
 if(a==='course-to-journal'){openEntry(null,null,course);return}
 if(a==='start-project'){openEntry(null,id);return}
 if(a==='zoom-tag-photo'){const p=D.projects.find(p=>p.id===id&&p.tutorial);if(p){const allowed=[p.coverPhoto,...p.steps.map(s=>s.photo)];if(allowed.includes(target.dataset.photo))openLightbox('./assets/'+encodeURIComponent(target.dataset.photo),target.dataset.caption||p.title)}return}
 if(a==='toggle-tag-step'){const p=D.projects.find(p=>p.id===id&&p.tutorial);if(!p)return;const n=Number(target.dataset.index);if(!Number.isInteger(n)||n<0||n>=p.steps.length)return;const key='project:'+id;const current=state.progress[key]||[];state.progress[key]=current.includes(n)?current.filter(x=>x!==n):[...current,n].sort((a,b)=>a-b);persist();render();document.getElementById('tag-etape-'+(n+1))?.scrollIntoView({block:'nearest',behavior:'instant'});return}
 if(a==='zoom-diagram'){const c=D.courses.find(c=>c.id===course),si=Number(target.dataset.step),vi=Number(target.dataset.view);if(c){const d=$('#lightbox');$('#lightbox-content').innerHTML=`<div style="max-width:min(88vw,850px)">${stepDiagram(c,si,vi)}<p style="margin:9px 0;text-align:center">${esc(c.steps[si].views[vi])} · Schéma de démonstration</p></div>`;d.showModal()}return}
 if(a==='close-lightbox'){$('#lightbox').close();return}
 if(a==='open-photo'){openLightbox(target.dataset.src,'Ma photographie');return}
 if(a==='new-entry'){openEntry();return}
 if(a==='edit-entry'){openEntry(id);return}
 if(a==='delete-entry'){let item=state.journal.find(x=>x.id===id);if(item&&confirm(`Supprimer définitivement « ${item.title} » et ses photos ?`)){state.journal=state.journal.filter(x=>x.id!==id);persist();render();toast('Création supprimée.')}return}
 if(a==='remove-draft-photo'){readDraftFields();draft.photos.splice(Number(target.dataset.index),1);showEntryModal();return}
 if(a==='new-inventory'){openInventory();return}
 if(a==='edit-inventory'){openInventory(id);return}
 if(a==='delete-inventory'){if(confirm('Supprimer cette fourniture ?')){state.inventory=state.inventory.filter(x=>x.id!==id);persist();render()}return}
 if(a==='new-swatch'){openSwatch();return}
 if(a==='edit-swatch'){openSwatch(id);return}
 if(a==='delete-swatch'){if(confirm('Supprimer cette couleur du nuancier ?')){state.swatches=state.swatches.filter(x=>x.id!==id);persist();render()}return}
 if(a==='close-modal'){modalClose();return}
 if(a==='release'){openRelease();return}
 if(a==='export'){exportData();return}
}
function submitForm(e){const f=e.target;if(!['entry-form','inventory-form','swatch-form'].includes(f.id))return;e.preventDefault();if(!f.reportValidity())return;const form=new FormData(f);const read=k=>String(form.get(k)||'').trim();if(f.id==='entry-form'){draft.title=read('title').slice(0,150);if(!draft.title){toast('Le titre est nécessaire.');return}for(let k of ['date','type','status','description','notes'])draft[k]=read(k);draft.updatedAt=new Date().toISOString();const ix=state.journal.findIndex(x=>x.id===draft.id);if(ix>=0)state.journal[ix]=draft;else state.journal.push(draft);modalClose();persist();render();toast('Création enregistrée dans ton carnet.');return}
if(f.id==='inventory-form'){draft.name=read('name').slice(0,150);if(!draft.name)return;for(let k of ['category','brand','color','notes'])draft[k]=read(k);draft.quantity=String(Math.max(1,Math.min(999,Number(read('quantity'))||1)));let ix=state.inventory.findIndex(x=>x.id===draft.id);if(ix>=0)state.inventory[ix]=draft;else state.inventory.push(draft);modalClose();persist();render();toast('Fourniture enregistrée.');return}
if(f.id==='swatch-form'){draft.name=read('name');if(!draft.name)return;for(let k of ['brand','family','paper','color','notes'])draft[k]=read(k);let ix=state.swatches.findIndex(x=>x.id===draft.id);if(ix>=0)state.swatches[ix]=draft;else state.swatches.push(draft);modalClose();persist();render();toast('Couleur enregistrée dans ton nuancier.');return}}
function onInputs(e){const el=e.target;if(el.id==='season-switch'){state.season=el.value;persist();render();return}if(el.id==='catalog-search'){filter.q=el.value;applyCatalog();return}if(el.id==='family-filter'){filter.family=el.value;applyCatalog();return}if(el.id==='category-filter'){filter.category=el.value;applyCatalog();return}if(el.id==='season-filter'){filter.season=el.value;applyCatalog();return}if(el.id==='fav-filter'){filter.onlyFav=el.checked;applyCatalog();return}if(el.id==='course-note'){state.notes[el.dataset.course]=el.value;persist();return}}
async function onFiles(e){const el=e.target;if(el.id==='restore-file'){const file=el.files?.[0];if(file)await restoreData(file);el.value='';return}if(el.id==='entry-photos'){if(!draft)return;readDraftFields();const files=Array.from(el.files||[]);const remaining=5-(draft.photos||[]).length;if(files.length>remaining)toast(`Limite de cinq photos : ${remaining} emplacement(s) restant(s).`);for(const file of files.slice(0,remaining)){try{const result=await downsize(file);draft.photos.push(result)}catch(err){console.error(err);toast('Impossible de lire cette photo. Essaie un format JPG ou PNG.')}}showEntryModal();return}}
function installListeners(){document.addEventListener('click',clickAction);document.addEventListener('submit',submitForm);document.addEventListener('input',onInputs);document.addEventListener('change',e=>{onInputs(e);if(e.target.type==='file')onFiles(e)});window.addEventListener('hashchange',()=>{if(route().page==='cours'&&route().id){state.lastCourse=route().id;persist()}render()});window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))modalClose()});$('#lightbox').addEventListener('click',e=>{if(e.target===$('#lightbox'))$('#lightbox').close()});$('#modal').addEventListener('close',()=>{draft=null;editingType=null})}
installListeners();boot().catch(err=>{console.error(err);$('#app').innerHTML=`<div class="error-banner"><h2>L’atelier n’a pas pu démarrer</h2><p>Recharge la page. Si le problème persiste, ouvre la console du navigateur.</p></div>`});
})();